var list = event.target_players
for p in list:
	actions.add_mark_skill(p, "poison", 1, "", "中毒", "中毒结算时受到 1 点伤害", true)

var list = game.get_all_players()
for p in list:
	var equip_cards = p.get_cards("equipment")
	if equip_cards.is_empty():
		actions.damage(p, 4, event["card"])
	elif await p.confirm("\"达克斯顿·贾格\": 是否弃置一张装备，否则受到 4 点伤害"):
		var chosen = await p.choose_card(1, equip_cards)
		if chosen.is_empty():
			actions.damage(p, 4, event["card"])
		else:
			actions.discard(p, chosen)
	else:
		actions.damage(p, 4, event["card"])

